CREATE TABLE "nova_agent_routine" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"ownerUserId" TEXT NOT NULL,"agentId" TEXT NOT NULL,"name" TEXT NOT NULL,"instructions" TEXT NOT NULL,"scheduleType" TEXT NOT NULL DEFAULT 'daily',"dayOfWeek" INTEGER,"hour" INTEGER NOT NULL,"minute" INTEGER NOT NULL,"timezone" TEXT NOT NULL,"requiresCalendar" BOOLEAN NOT NULL DEFAULT false,"separateThread" BOOLEAN NOT NULL DEFAULT false,"status" TEXT NOT NULL DEFAULT 'active',"lastRunAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "nova_agent_routine_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nova_agent_routine_run" ("id" TEXT NOT NULL,"routineId" TEXT NOT NULL,"deliveryId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'queued',"reason" TEXT,"agentSessionId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "nova_agent_routine_run_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "nova_agent_routine_run_agentSessionId_key" ON "nova_agent_routine_run"("agentSessionId"); CREATE UNIQUE INDEX "nova_agent_routine_run_routineId_deliveryId_key" ON "nova_agent_routine_run"("routineId","deliveryId");
CREATE INDEX "nova_agent_routine_organizationId_agentId_status_idx" ON "nova_agent_routine"("organizationId","agentId","status"); CREATE INDEX "nova_agent_routine_ownerUserId_createdAt_idx" ON "nova_agent_routine"("ownerUserId","createdAt"); CREATE INDEX "nova_agent_routine_run_routineId_createdAt_idx" ON "nova_agent_routine_run"("routineId","createdAt"); CREATE INDEX "nova_agent_routine_run_status_createdAt_idx" ON "nova_agent_routine_run"("status","createdAt");
ALTER TABLE "nova_agent_routine" ADD CONSTRAINT "nova_agent_routine_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "nova_agent_routine" ADD CONSTRAINT "nova_agent_routine_ownerUserId_fkey" FOREIGN KEY ("ownerUserId") REFERENCES "user"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "nova_agent_routine" ADD CONSTRAINT "nova_agent_routine_agentId_fkey" FOREIGN KEY ("agentId") REFERENCES "nova_agent"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "nova_agent_routine_run" ADD CONSTRAINT "nova_agent_routine_run_routineId_fkey" FOREIGN KEY ("routineId") REFERENCES "nova_agent_routine"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "nova_agent_routine_run" ADD CONSTRAINT "nova_agent_routine_run_agentSessionId_fkey" FOREIGN KEY ("agentSessionId") REFERENCES "agent_session"("id") ON DELETE SET NULL ON UPDATE CASCADE;
